WITH latest AS (SELECT * FROM shipments QUALIFY ROW_NUMBER() OVER (PARTITION BY order_id, status ORDER BY delivered_date NULLS LAST, id) = 1) SELECT CASE WHEN cost >= 90 THEN 'LARGE' ELSE 'SMALL' END AS cost_tier, DATE_TRUNC('MONTH', shipped_date) AS activity_month, COUNT(CASE WHEN status = 'LOST' THEN 1 END) AS lost_count, COUNT(DISTINCT status) AS distinct_status FROM latest GROUP BY GROUPING SETS ((CASE WHEN cost >= 90 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('MONTH', shipped_date)), (CASE WHEN cost >= 90 THEN 'LARGE' ELSE 'SMALL' END), ()) ORDER BY cost_tier DESC;
